package br.com.admeclesial.interfaces.rest.projeto;
import br.com.admeclesial.application.projeto.*; import br.com.admeclesial.domain.projeto.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/recursos-vinculados") public class RecursoVinculadoRestController { final RecursoVinculadoApplicationService s; public RecursoVinculadoRestController(RecursoVinculadoApplicationService s){this.s=s;} @PostMapping public RecursoVinculado criar(@Valid @RequestBody RecursoVinculadoRequest r){return s.criar(r);} @GetMapping public List<RecursoVinculado> listar(){return s.listar();} @GetMapping("/{uuid}") public RecursoVinculado buscar(@PathVariable UUID uuid){return s.buscar(uuid);} @PostMapping("/utilizacoes") public UtilizacaoRecurso utilizar(@Valid @RequestBody UtilizacaoRecursoRequest r){return s.utilizar(r);} }
